import {SPECIES} from './world.js';
import {stageName} from './time.js';
import {AUCTION_KINDS,BIDDERS,auctionCandidates,auctionBug,marketValue} from './auctions.js';
import {lineBadge} from './line-ui.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n).toLocaleString('ko-KR');
export const auctionDate=at=>new Date(at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false});
export function auctionRemaining(ends,now=Date.now()){
 const seconds=Math.max(0,Math.ceil((ends-now)/1000)),minutes=Math.floor(seconds/60),hours=Math.floor(minutes/60),days=Math.floor(hours/24);
 return days?`${days}일 ${hours%24}시간`:hours?`${hours}시간 ${minutes%60}분`:`${minutes}분 ${seconds%60}초`;
}
export function updateAuctionClocks(now=Date.now()){document.querySelectorAll('[data-auction-end]').forEach(el=>el.textContent=auctionRemaining(Number(el.dataset.auctionEnd),now));}
const statusName=s=>({active:'진행 중',sold:'낙찰',unsold:'유찰·반환',cancelled:'취소·반환'})[s];
function title(kind,asset){const b=kind==='specimen'?asset.bug:asset;return kind==='larva'?`${SPECIES[b.species].name} · ${stageName(asset)} 유충 3마리`:`${b.name} · ${b.sex==='male'?'♂':'♀'} ${b.length.toFixed(1)} mm`;}
function picture(kind,asset,{art}){return kind==='larva'?`<canvas class="brood-canvas auction-larva-art" data-stage="${stageName(asset)}" data-species="${asset.species}" width="90" height="90" role="img" aria-label="${SPECIES[asset.species].name} ${stageName(asset)} 유충 묶음"></canvas>`:art(kind==='specimen'?asset.bug:asset);}
function identity(state,kind,asset,{traitBadges}){
 if(kind!=='larva'){const b=kind==='specimen'?asset.bug:asset;return `${lineBadge(state,b)}${traitBadges(b)}${kind==='adult'?`<small>건강 ${b.health} · ${b.born}일째 획득</small>`:`<small>완성 표본 · 사육자 ${esc(asset.work.label.collector||'미기입')}</small>`}`;}
 return `${lineBadge(state,asset)}<p class="auction-parents">부모 ♂ ${asset.parents[0].length.toFixed(1)} mm × ♀ ${asset.parents[1].length.toFixed(1)} mm</p><div class="auction-parent-traits">${asset.parents.map(p=>`<div><small>${p.sex==='male'?'부':'모'}의 특성</small>${traitBadges(p)}</div>`).join('')}</div><small>유충 성별 미확인 · 부모 특성은 유전 기대치에 반영</small>`;
}
export function auctionForm(state,draft,helpers){
 const kind=Object.hasOwn(AUCTION_KINDS,draft.kind)?draft.kind:'adult',items=auctionCandidates(state,kind);
 if(!items.some(a=>a.id===draft.assetId))draft.assetId=items[0]?.id||'';
 const asset=items.find(a=>a.id===draft.assetId),market=asset?marketValue(kind,asset):null;
 if(draft.startPrice===undefined)draft.startPrice=market?.suggested||1;
 const periods=[['1','1분'],['10','10분'],['60','1시간'],['360','6시간'],['1440','1일'],['4320','3일'],['10080','7일'],['custom','직접 입력']];
 return `<form id="auction-form"><div class="auction-form-grid"><label>출품 종류<select class="field" id="auction-kind" name="kind">${Object.entries(AUCTION_KINDS).map(([id,name])=>`<option value="${id}" ${id===kind?'selected':''}>${name}</option>`).join('')}</select></label><label>출품 대상<select class="field" id="auction-asset" name="asset">${items.map(a=>`<option value="${esc(a.id)}" ${a.id===draft.assetId?'selected':''}>${esc(title(kind,a))}</option>`).join('')||'<option value="">출품 가능한 개체 없음</option>'}</select></label></div>${asset?`<div class="auction-preview"><div>${picture(kind,asset,helpers)}</div><div><strong>${esc(title(kind,asset))}</strong>${identity(state,kind,asset,helpers)}</div></div><div class="auction-estimate"><strong>참고 예상가 ${money(market.low)}~${money(market.high)} 잎사귀</strong><span>관심 ${market.demand<.2?'낮음':market.demand<.55?'보통':'높음'} · 낙찰 보장 없음</span><ul>${market.factors.map(f=>`<li>${esc(f)}</li>`).join('')}</ul></div>`:`<p class="empty">${kind==='larva'?'번식통의 1·2·3령 유충을 3마리 묶음으로 출품할 수 있어요. 알·번데기는 출품하지 않습니다.':kind==='specimen'?'표본 제작과 케이스 보관까지 마친 개체가 필요해요.':'채집·번식으로 얻은 성충을 출품할 수 있어요.'}</p>`}<div class="auction-form-grid"><label>입찰 시작가 · 잎사귀<input class="field" id="auction-start" name="start" type="number" min="1" max="1000000" step="1" value="${esc(draft.startPrice)}" required inputmode="numeric"></label><label>경매 기간 · 실제 시간<select class="field" id="auction-duration" name="duration">${periods.map(([id,text])=>`<option value="${id}" ${id===(draft.duration||'10')?'selected':''}>${text}</option>`).join('')}</select></label></div><label class="field-label ${draft.duration==='custom'?'':'auction-hidden'}" id="auction-custom-label">직접 입력 · 1~10,080분<input class="field" id="auction-minutes" name="minutes" type="number" min="1" max="10080" step="1" inputmode="numeric" value="${esc(draft.minutes||10)}" ${draft.duration==='custom'?'required':'disabled'}></label><p id="auction-price-note" class="auction-price-note" data-market-high="${market?.high||0}">${market&&Number(draft.startPrice)>market.high?'예상 범위보다 높은 시작가예요. 입찰이 없을 수 있습니다.':'최저가는 시작가입니다. 입찰자가 한 명이면 시작가에 낙찰될 수 있어요.'}</p><p class="auction-custody-note">성충·유충은 출품 중 위탁 보관되어 사육·번식·성장이 잠시 멈춥니다. 유찰·입찰 전 취소 시 그대로 돌아오며, 반환 공간은 미리 확보합니다. 표본은 케이스에 출품 표시가 붙고 낙찰 때 이동합니다. 입찰 후 취소는 불가능합니다.</p><div class="modal-buttons"><button type="button" class="btn quiet" data-action="close">닫기</button><button class="btn primary" type="submit" ${asset?'':'disabled'}>경매에 출품</button></div></form>`;
}
export function auctionScreen(state,ui,helpers){
 const {btn}=helpers,all=state.auctions||[],active=all.filter(a=>a.status==='active');
 const matchesStatus=a=>ui.auctionStatus==='all'||(ui.auctionStatus==='history'?a.status!=='active':a.status==='active');
 const filtered=all.filter(a=>(ui.auctionKind==='all'||a.kind===ui.auctionKind)&&matchesStatus(a)).slice().reverse();
 return `<div class="screen-heading"><div><h2>곤충 경매장</h2><p>가상 수집가들이 크기·희귀 특성·부모세대를 살펴 입찰합니다.</p></div>${btn('새 경매 출품','auction-new','primary')}</div><div class="auction-summary"><div><strong>${active.length} / 8</strong><span>진행 중</span></div><div><strong>${all.filter(a=>a.status==='sold').length}</strong><span>최근 낙찰</span></div><div><strong>${money(all.filter(a=>a.status==='sold').reduce((n,a)=>n+a.current,0))}</strong><span>최근 거래 수익 · 잎사귀</span></div></div><div class="auction-filters"><label>종류<select id="auction-filter-kind" class="field">${[['all','모든 출품'],...Object.entries(AUCTION_KINDS)].map(([id,name])=>`<option value="${id}" ${id===ui.auctionKind?'selected':''}>${name}</option>`).join('')}</select></label><label>목록<select id="auction-filter-status" class="field">${[['active','진행 중'],['history','종료 기록'],['all','전체']].map(([id,name])=>`<option value="${id}" ${id===ui.auctionStatus?'selected':''}>${name}</option>`).join('')}</select></label></div><div class="auction-list">${filtered.map(a=>`<article class="auction-card ${a.status}"><div class="auction-card-head"><span class="auction-kind">${AUCTION_KINDS[a.kind]}</span><span class="auction-status ${a.status}">${statusName(a.status)}</span></div><div class="auction-lot"><div class="auction-picture">${picture(a.kind,a.asset,helpers)}</div><div class="auction-identity"><h3>${esc(title(a.kind,a.asset))}</h3>${identity(state,a.kind,a.asset,helpers)}</div></div><div class="auction-price"><div><span>${a.status==='sold'?'낙찰가':a.current?'현재 입찰가':'입찰 대기 · 시작가'}</span><strong>${money(a.current||a.startPrice)} <small>잎사귀</small></strong></div><span>${a.bids.length}건 입찰</span></div><div class="auction-timing">${a.status==='active'?`<strong data-auction-end="${a.ends}">${auctionRemaining(a.ends)}</strong> 남음`:`<strong>${statusName(a.status)}</strong>`}<small>${auctionDate(a.ends)} 종료 · 한국 시각</small></div>${a.buyer!==null?`<p class="auction-buyer">${a.status==='sold'?'낙찰자':'현재 최고 입찰자'} · ${BIDDERS[a.buyer]}</p>`:'<p class="auction-buyer">입찰자가 아직 없어요.</p>'}${a.status==='unsold'||a.status==='cancelled'?'<p class="auction-returned">개체를 반환했어요. 다른 시작가로 다시 출품할 수 있습니다.</p>':''}<details class="auction-bid-history"><summary>입찰 내역 · ${a.bids.length}건</summary>${a.bids.slice().reverse().map(b=>`<div><time>${auctionDate(b.at)}</time><span>${BIDDERS[b.bidder]}${b.bidder!==b.challenger?' · 자동 응찰':''}</span><strong>${money(b.amount)}</strong></div>`).join('')||'<p>아직 입찰이 없습니다.</p>'}</details><details class="auction-valuation"><summary>출품 시 참고 예상가 ${money(a.market.low)}~${money(a.market.high)} 잎사귀 · 평가 기준</summary><ul>${a.market.factors.map(f=>`<li>${esc(f)}</li>`).join('')}</ul></details>${a.status==='active'?btn(a.bids.length?'입찰 후 취소 불가':'입찰 전 출품 취소','auction-cancel','quiet full',`data-id="${esc(a.id)}" ${a.bids.length?'disabled':''}`):''}</article>`).join('')||'<section class="panel auction-empty"><h3>표시할 경매가 없어요.</h3><p>성충, 유충 묶음, 완성 표본을 골라 시작가와 경매 기간을 정해 보세요.</p></section>'}</div><section class="panel auction-guide"><h3>경매 안내</h3><p>입찰은 가상 입찰자가 진행합니다. 두 숲 모두 실제 시간으로 진행되고, 자리를 비운 동안의 입찰·종료도 다음 접속 때 반영됩니다. 다음 날 버튼으로 경매 시간을 넘길 수는 없습니다.</p><p>크기는 같은 종·같은 성별에서 비교합니다. 작은 기본형은 관심이 적어 헐값에 낙찰되거나 유찰될 수 있어요. 특성별 자연 발현 확률이 낮을수록 더 높은 평가액과 수집 수요를 받습니다. 대형 개체와 대형 부모의 유충도 더 높은 예산의 수집가들이 관심을 보입니다. 유충은 부모 특성의 희귀도와 유전 확률을 함께 반영하며, 암컷의 큰 크기와 특성도 평가합니다.</p><p>입찰자는 각자의 한도까지 자동 응찰하며 마감 가까이 경쟁할 수도 있습니다. 기간을 늘려도 매번 입찰이 들어오지는 않습니다. 낙찰 대금은 종료 때 자동으로 잎사귀에 더해집니다.</p><details><summary>실제 출품 참고</summary><p>몸길이·부모 크기·혈통·희귀 특성·표본 정보와 시작가·입찰 기록을 참고했습니다. 예상 가격과 입찰 빈도는 잎사귀 경제에 맞춘 게임 설정입니다.</p><div class="auction-source-links"><a href="https://auctions.yahoo.co.jp/closedsearch/closedsearch/2084061390" target="_blank" rel="noopener">사슴벌레 성충·혈통 출품</a><a href="https://auctions.yahoo.co.jp/closedsearch/closedsearch/2084061395" target="_blank" rel="noopener">국산 유충 출품</a><a href="https://auctions.yahoo.co.jp/closedsearch/closedsearch/2084061404" target="_blank" rel="noopener">곤충 표본 출품</a></div></details></section>`;
}
